package com.github.tartaricacid.touhoulittlemaid.compat.top.provider;

import com.github.tartaricacid.touhoulittlemaid.item.ItemMaidBeacon;
import com.github.tartaricacid.touhoulittlemaid.tileentity.TileEntityMaidBeacon;
import mcjty.theoneprobe.api.ElementAlignment;
import mcjty.theoneprobe.api.IBlockDisplayOverride;
import mcjty.theoneprobe.api.IProbeConfig;
import mcjty.theoneprobe.api.IProbeHitData;
import mcjty.theoneprobe.api.IProbeInfo;
import mcjty.theoneprobe.api.ProbeMode;
import mcjty.theoneprobe.apiimpl.providers.DefaultProbeInfoProvider;
import mcjty.theoneprobe.config.Config;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

public class ShrineLampProvider
implements IBlockDisplayOverride {
    public boolean overrideStandardInfo(ProbeMode mode, IProbeInfo probeInfo, Player player, Level world, BlockState blockState, IProbeHitData data) {
        BlockEntity te = world.m_7702_(data.getPos());
        if (te instanceof TileEntityMaidBeacon) {
            TileEntityMaidBeacon lamp = (TileEntityMaidBeacon)te;
            DefaultProbeInfoProvider.showStandardBlockInfo((IProbeConfig)Config.getRealConfig(), (ProbeMode)mode, (IProbeInfo)probeInfo, (BlockState)blockState, (Block)blockState.m_60734_(), (Level)world, (BlockPos)data.getPos(), (Player)player, (IProbeHitData)data);
            float storagePower = lamp.getStoragePower();
            float costPower = lamp.getEffectCost() * 900.0f;
            probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)Component.m_237110_((String)"tooltips.touhou_little_maid.maid_beacon.desc", (Object[])new Object[]{ItemMaidBeacon.DECIMAL_FORMAT.format(storagePower)}));
            if (lamp.getPotionIndex() == -1) {
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)Component.m_237110_((String)"gui.touhou_little_maid.maid_beacon.cost_power", (Object[])new Object[]{ItemMaidBeacon.DECIMAL_FORMAT.format(0L)}));
            } else {
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)Component.m_237110_((String)"gui.touhou_little_maid.maid_beacon.cost_power", (Object[])new Object[]{ItemMaidBeacon.DECIMAL_FORMAT.format(costPower)}));
            }
            return true;
        }
        return false;
    }
}

